#pragma once

static const char JRBOT_WEB_V1_HTML[]=
"<!doctype html><html lang='pt-br'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'>"
"<title>JrBot V1</title><style>"
":root{color-scheme:dark;--bg:#09111e;--card:#132036;--line:#29415f;--text:#f5f8ff;--muted:#9fb1ca;--a:#5ea7ff;--b:#896eff;--ok:#63d99b;--bad:#ff8585}*{box-sizing:border-box}body{margin:0;background:linear-gradient(#0c1b35,#09111e 300px);color:var(--text);font:15px system-ui,-apple-system,Segoe UI,sans-serif}main{max-width:820px;margin:auto;padding:20px 14px 46px}.top{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:17px}h1{margin:0;font-size:28px}.sub{color:var(--muted);font-size:13px}.pill{border:1px solid var(--line);border-radius:99px;padding:7px 10px}.dot{display:inline-block;width:9px;height:9px;border-radius:50%;background:var(--bad);margin-right:6px}.dot.ok{background:var(--ok)}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.stat,.card{background:var(--card);border:1px solid var(--line);border-radius:16px}.stat{padding:12px}.stat small{display:block;color:var(--muted);margin-bottom:4px}.card{padding:16px;margin:11px 0}.card h2{font-size:17px;margin:0 0 13px}.faces{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}button,a.action,label.action{border:1px solid var(--line);background:#1a2a43;color:var(--text);border-radius:11px;padding:11px 12px;font:inherit;cursor:pointer;text-decoration:none;text-align:center}.primary{background:linear-gradient(135deg,var(--a),var(--b));border-color:#7394ff;font-weight:650}.row{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.grow{flex:1}.hint{color:var(--muted);font-size:12px;line-height:1.4;margin-top:8px}select{background:#1a2a43;color:var(--text);border:1px solid var(--line);border-radius:9px;padding:10px}input[type=range]{width:100%}input[type=file]{display:none}audio{width:100%;margin-top:11px}.camera{width:100%;aspect-ratio:4/3;object-fit:contain;background:#05090f;border:1px solid var(--line);border-radius:13px}.placeholder{min-height:210px;display:flex;align-items:center;justify-content:center;border:1px dashed var(--line);border-radius:13px;color:var(--muted)}.feedback{min-height:20px;color:var(--muted);font-size:13px;margin:15px 2px}.feedback.err{color:var(--bad)}.foot{color:var(--muted);font-size:12px;border-top:1px solid var(--line);padding-top:13px;margin-top:20px}@media(max-width:600px){main{padding:14px 10px 36px}.grid{grid-template-columns:1fr 1fr}.faces{grid-template-columns:repeat(2,1fr)}button,a.action,label.action{min-height:45px}.card{padding:14px}}"
"</style></head><body><main>"
"<div class='top'><div><h1>JrBot</h1><div class='sub'>V1 · painel local · JRBOT-WEB-V1-02</div></div><div class='pill sub'><span id='dot' class='dot'></span><span id='conn'>Conectando</span></div></div>"
"<div class='grid'><div class='stat'><small>Face</small><b id='face'>—</b></div><div class='stat'><small>Volume</small><b id='volume'>—</b></div><div class='stat'><small>Microfone</small><b id='mic'>—</b></div><div class='stat'><small>Wi-Fi</small><b id='wifi'>—</b></div><div class='stat'><small>IP</small><b id='ip'>—</b></div><div class='stat'><small>Firmware</small><b id='fw'>—</b></div></div>"
"<section class='card'><h2>Rosto</h2><div id='faces-main' class='faces'></div><details><summary>Mais expressões</summary><div id='faces-more' class='faces' style='margin-top:9px'></div></details></section>"
"<section class='card'><h2>Câmera</h2><div id='cam-empty' class='placeholder'>Toque em Atualizar foto.</div><img id='camera' class='camera' alt='Câmera do JrBot' hidden><div class='row' style='margin-top:10px'><button id='cam-btn' class='primary grow'>Atualizar foto</button><a id='cam-save' class='action grow' download='jrbot-camera.jpg' hidden>Salvar foto</a></div><div class='hint'>Captura sob demanda da OV5640.</div></section>"
"<section class='card'><h2>Áudio do celular / computador</h2><div class='row'><label class='action primary grow' for='audio-file'>Escolher WAV e tocar</label></div><input id='audio-file' type='file' accept='.wav,audio/wav'><div class='hint'>Formato desta candidata: WAV PCM 16-bit, mono, 16 kHz, máximo de 10 segundos.</div></section>"
"<section class='card'><h2>Microfone do JrBot</h2><div class='row'><label>Gravar</label><select id='seconds'><option value='1'>1 s</option><option value='3' selected>3 s</option><option value='5'>5 s</option><option value='10'>10 s</option></select><button id='record' class='primary'>Gravar áudio</button></div><audio id='player' controls hidden></audio><div id='record-actions' class='row' style='margin-top:10px' hidden><a id='download' class='action grow'>Baixar WAV</a><button id='play-recording' class='grow'>Tocar no JrBot</button></div></section>"
"<section class='card'><h2>Som</h2><div class='row'><span>Volume</span><b id='vol-label'>35</b></div><input id='vol' type='range' min='0' max='100' value='35'><div class='row' style='margin-top:12px'><button id='apply-volume' class='primary grow'>Aplicar volume</button><button id='test-sound' class='grow'>Testar som</button></div></section>"
"<div id='feedback' class='feedback'>Pronto.</div><div class='foot'>Controle local do JrBot. Sem autenticação/TLS: use somente na rede local confiável.</div>"
"<script>const q=i=>document.getElementById(i),mf=[['neutro','Neutro'],['feliz','Feliz'],['pensando','Pensando'],['surpreso','Surpreso'],['triste','Triste'],['sono','Sono'],['amor','Amor'],['cool','Cool']],xf=[['animado','Animado'],['bravo','Bravo'],['cetico','Cético'],['confuso','Confuso'],['piscando','Piscando'],['brincalhao','Brincalhão'],['preocupado','Preocupado'],['bateria','Bateria']];let busy=false,recUrl=null,camUrl=null;function fb(t,e=false){q('feedback').textContent=t;q('feedback').className='feedback'+(e?' err':'')}function faces(id,a){for(const f of a){const b=document.createElement('button');b.textContent=f[1];b.onclick=()=>cmd(f[0],'Face: '+f[1]);q(id).appendChild(b)}}faces('faces-main',mf);faces('faces-more',xf);async function send(c){const r=await fetch('/cmd',{method:'POST',headers:{'Content-Type':'text/plain','X-JrBot-Command':'1'},body:c}),t=await r.text();if(!r.ok)throw Error(t);return t}async function cmd(c,m){if(busy)return;busy=true;try{await send(c);fb(m);await status(true)}catch(e){fb('Erro: '+e.message,true)}finally{busy=false}}async function camera(){if(busy)return;busy=true;try{fb('Capturando foto...');const r=await fetch('/capture?t='+Date.now(),{cache:'no-store'});if(!r.ok)throw Error(await r.text());const b=await r.blob();if(camUrl)URL.revokeObjectURL(camUrl);camUrl=URL.createObjectURL(b);q('camera').src=camUrl;q('camera').hidden=false;q('cam-empty').hidden=true;q('cam-save').href=camUrl;q('cam-save').hidden=false;fb('Foto atualizada.')}catch(e){fb('Erro na câmera: '+e.message,true)}finally{busy=false}}async function audio(f){if(!f||busy)return;busy=true;try{fb('Enviando áudio...');const r=await fetch('/audio',{method:'POST',headers:{'Content-Type':'audio/wav','X-JrBot-Audio':'1'},body:f}),t=await r.text();if(!r.ok)throw Error(t);fb('Áudio reproduzido no JrBot.')}catch(e){fb('Erro no áudio: '+e.message,true)}finally{busy=false;q('audio-file').value=''}}async function record(){if(busy)return;busy=true;try{fb('Gravando...');const r=await fetch('/mic-record?seconds='+q('seconds').value,{cache:'no-store'});if(!r.ok)throw Error(await r.text());const b=await r.blob();if(recUrl)URL.revokeObjectURL(recUrl);recUrl=URL.createObjectURL(b);q('player').src=recUrl;q('player').hidden=false;q('download').href=recUrl;q('download').download='jrbot-microfone.wav';q('record-actions').hidden=false;fb('Gravação concluída.')}catch(e){fb('Erro na gravação: '+e.message,true)}finally{busy=false;await status(true)}}function parse(t){const o={};for(const p of t.trim().split(/\\s+/)){const i=p.indexOf('=');if(i>0)o[p.slice(0,i)]=p.slice(i+1)}return o}async function status(force=false){if(busy&&!force)return;try{const r=await fetch('/status',{cache:'no-store'}),s=parse(await r.text());if(!r.ok)throw Error('status');q('dot').className='dot ok';q('conn').textContent='Online';q('face').textContent=s.expression||'—';q('volume').textContent=(s.volume||'—')+(s.volume?'%':'');q('mic').textContent=s.mic||'—';q('wifi').textContent=s.wifi==='1'?'Conectado':'Desconectado';q('ip').textContent=s.ip||'—';q('fw').textContent=s.version||'—';if(s.volume){q('vol').value=s.volume;q('vol-label').textContent=s.volume}}catch(e){q('dot').className='dot';q('conn').textContent='Offline'}}q('cam-btn').onclick=camera;q('audio-file').onchange=e=>audio(e.target.files[0]);q('record').onclick=record;q('play-recording').onclick=()=>cmd('audio_play_recording','Reproduzindo gravação');q('apply-volume').onclick=()=>cmd('audio_volume '+q('vol').value,'Volume ajustado');q('test-sound').onclick=()=>cmd('audio_test','Teste de som enviado');q('vol').oninput=()=>q('vol-label').textContent=q('vol').value;status();setInterval(()=>status(false),10000);</script>"
"</main></body></html>";
